add_task(async function test_inputChangeAndToggleAll() {
  abSyncSubview.setState(addressBooks);
  // Three address books should appear.
  await BrowserTestUtils.waitForMutationCondition(
    abSyncSubview.querySelector("#addressBooks"),
    {
      subtree: true,
      childList: true,
    },
    () =>
      abSyncSubview.querySelectorAll("#addressBookAccountsContainer input")
        .length === 3
  );
  await TestUtils.waitForTick();

  const firstAddressBookCheckbox = abSyncSubview.querySelector(
    "#addressBookAccountsContainer input"
  );
  const selectAllAddressBooks = abSyncSubview.querySelector(
    "#selectAllAddressBooks"
  );
  Assert.ok(
    selectAllAddressBooks.checked,
    "Select all input should be checked"
  );
  Assert.ok(
    !selectAllAddressBooks.indeterminate,
    "Select all input should not be indeterminate"
  );
  Assert.ok(
    !firstAddressBookCheckbox.disabled,
    `first ab checkbox should be enabled`
  );
  Assert.ok(
    firstAddressBookCheckbox.offsetParent,
    `first ab checkbox should be visible`
  );
  firstAddressBookCheckbox.click();
  await TestUtils.waitForTick();
  Assert.ok(
    !firstAddressBookCheckbox.checked,
    "first ab checkbox should be unchecked after click"
  );

  const selectAllAddressBooksLabel = abSyncSubview.querySelector(
    `[for="selectAllAddressBooks"] span`
  );

  Assert.equal(
    abSyncSubview.l10n.getAttributes(selectAllAddressBooksLabel).id,
    "account-hub-select-all",
    "Address book select toggle should be select all"
  );

  Assert.ok(
    !selectAllAddressBooks.checked,
    "Select all input should not be checked"
  );
  Assert.ok(
    selectAllAddressBooks.indeterminate,
    "Select all input should be indeterminate"
  );

  Assert.equal(
    abSyncSubview.l10n.getAttributes(
      abSyncSubview.querySelector("#selectedAddressBooks")
    ).args.count,
    addressBooks.length - 1,
    "Address books count should update as one book was deselected"
  );

  // Toggle select all.
  selectAllAddressBooksLabel.click();

  await BrowserTestUtils.waitForMutationCondition(
    abSyncSubview.querySelector("#addressBookAccountsContainer"),
    {
      attributes: true,
      subtree: true,
      childList: true,
    },
    () =>
      abSyncSubview.querySelectorAll(
        "#addressBookAccountsContainer input:checked"
      ).length === addressBooks.length
  );

  Assert.equal(
    abSyncSubview.l10n.getAttributes(selectAllAddressBooksLabel).id,
    "account-hub-deselect-all",
    "Address book select toggle should be select all"
  );
  Assert.equal(
    abSyncSubview.l10n.getAttributes(
      abSyncSubview.querySelector("#selectedAddressBooks")
    ).args.count,
    addressBooks.length,
    "Address books count should update"
  );

  Assert.ok(
    selectAllAddressBooks.checked,
    "Select all input should be checked"
  );
  Assert.ok(
    !selectAllAddressBooks.indeterminate,
    "Select all input should not be indeterminate"
  );

  selectAllAddressBooksLabel.click();

  await BrowserTestUtils.waitForMutationCondition(
    selectAllAddressBooks,
    { attributes: true },
    () => !selectAllAddressBooks.checked
  );

  Assert.equal(
    abSyncSubview.l10n.getAttributes(selectAllAddressBooksLabel).id,
    "account-hub-select-all",
    "Address book select toggle should be select all"
  );

  Assert.ok(
    !selectAllAddressBooks.checked,
    "Select all input should not be checked"
  );
  Assert.ok(
    selectAllAddressBooks.indeterminate,
    "Select all input should not be indeterminate since the one pre-existing ab is still selected"
  );

  // Only the one pre-existing ab should be selected now.
  Assert.equal(
    abSyncSubview.l10n.getAttributes(
      abSyncSubview.querySelector("#selectedAddressBooks")
    ).args.count,
    1,
    "Address books count should update"
  );

  abSyncSubview.resetState();
});
